import { InterfaceMode } from "#core/ui/interface-modes/interface-modes.js";
import LensManager from "#core/ui/lenses/lens-manager.js";

/**
 * Handler for INTERFACEMODE_HOTSEAT.
 */
class HotseatInterfaceMode implements InterfaceMode.Handler {
	transitionTo(_oldMode: InterfaceMode.ModeId, _newMode: InterfaceMode.ModeId, _context?: object) {
		LensManager.setActiveLens("fxs-hotseat-lens");
	}

	transitionFrom(_oldMode: InterfaceMode.ModeId, _newMode: InterfaceMode.ModeId) {
		// Do nothing.
	}
}

InterfaceMode.addHandler("INTERFACEMODE_HOTSEAT", new HotseatInterfaceMode());
